<?php
namespace App\Http\Controllers;
use App\Exports\TransportOperationExport;use App\Models\TransportService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Maatwebsite\Excel\Facades\Excel;
class TransportOperationalReportController extends Controller { private function own(TransportService$s):void{abort_unless((int)$s->company_id===(int)auth()->user()->company_id,404);} public function service(TransportService$s){$this->own($s);$s->load(['vehicle','driver.employee','monitor.employee','actualVehicle','actualDriver.employee','actualMonitor.employee','passengers','issues','receiver','arrivalSignature']);$signature=null;if($s->arrivalSignature&&auth()->user()->can('transporte.firmas.ver'))$signature='data:image/png;base64,'.base64_encode(Storage::disk(config('attendance.disk','local'))->get($s->arrivalSignature->file_path));return Pdf::loadView('pdf.transport_service',compact('s','signature'))->download('servicio-transporte-'.$s->uuid.'.pdf');} public function weekly(Request$r){$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from']);$services=TransportService::forCompany($r->user()->company_id)->with('receiver')->whereBetween('service_date',[$r->from,$r->to])->orderBy('scheduled_arrival_at')->get();return Pdf::loadView('pdf.transport_weekly_arrivals',['services'=>$services,'company'=>$r->user()->company])->setPaper('a4','landscape')->download('control-semanal-llegadas.pdf');} public function excel(Request$r){return Excel::download(new TransportOperationExport($r->user()->company_id,$r->only(['from','to'])),'operacion-transporte.xlsx');} }
